CREATE TABLE app_user(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE role(id text PRIMARY KEY);
CREATE TABLE permission(id text PRIMARY KEY);
CREATE TABLE role_permission(role_id text REFERENCES role, permission_id text REFERENCES permission, PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_role(user_id uuid REFERENCES app_user, role_id text REFERENCES role, PRIMARY KEY(user_id,role_id));
CREATE TABLE auth_session(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,expires_at timestamptz NOT NULL);
CREATE TABLE login_attempt(key text PRIMARY KEY,attempts integer NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE client(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), first_name text NOT NULL,last_name text NOT NULL,phone text NOT NULL,email text,source text NOT NULL DEFAULT 'Saisie manuelle',status text NOT NULL DEFAULT 'Prospect' CHECK(status IN ('Prospect','Actif','Terminé','Archivé')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_type(id text PRIMARY KEY,label text NOT NULL,active boolean NOT NULL DEFAULT true,pricing_mode text NOT NULL DEFAULT 'hourly' CHECK(pricing_mode IN ('hourly','quote')));
CREATE TABLE vehicle_model(id text PRIMARY KEY,label text NOT NULL);
CREATE TABLE tariff_version(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),model text NOT NULL REFERENCES vehicle_model,support text NOT NULL CHECK(support IN ('GoPermis','Personnel')),cents integer NOT NULL CHECK(cents>0),valid_from date NOT NULL,valid_to date,CHECK(valid_to IS NULL OR valid_to>valid_from),UNIQUE(model,support,valid_from));
CREATE TABLE offer(id text PRIMARY KEY,label text NOT NULL,paid_minutes integer NOT NULL CHECK(paid_minutes>0),bonus_minutes integer NOT NULL CHECK(bonus_minutes>=0),single_payment boolean NOT NULL DEFAULT true,active boolean NOT NULL DEFAULT true);
CREATE TABLE service(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES client,type_id text NOT NULL REFERENCES service_type,status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Brouillon','Active','Terminée')),price_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service_id uuid NOT NULL REFERENCES service,amount_cents integer NOT NULL CHECK(amount_cents>0),method text NOT NULL CHECK(method IN ('Carte','Virement','Espèces')),created_by uuid NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL UNIQUE);
CREATE TABLE hour_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service_id uuid NOT NULL REFERENCES service,minutes integer NOT NULL CHECK(minutes<>0),kind text NOT NULL CHECK(kind IN ('purchase','bonus','session','adjustment')),reason text NOT NULL,created_by uuid NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_purchase ON hour_ledger(service_id) WHERE kind='purchase';
CREATE UNIQUE INDEX one_bonus ON hour_ledger(service_id) WHERE kind='bonus';
CREATE TABLE note(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES client,body text NOT NULL,created_by uuid NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES app_user,action text NOT NULL,resource_id uuid NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO role VALUES ('technical_admin'),('manager'),('administration'),('instructor');
